package com.example.rokidgeminisecretary;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.widget.*;import java.io.*;import java.util.*;
public final class RecorderGalleryActivity extends Activity {
 private final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();private static final int PAGE_SIZE=60;private int pageStart;private volatile int generation;private File selected;private Bitmap current;private AlertDialog photoDialog;private RecorderPhotoZoomView photoView;private TextView photoCaption;private boolean listDirty;private int previewGeneration;private final Set<File> checked=new HashSet<>();private TextView selectionCount;private Button bulkSave,bulkDelete,previewSave,deleteAll;private boolean batchBusy;private File[] permissionPendingBatch;private int shownCount=-1;private final Handler refreshHandler=new Handler(Looper.getMainLooper());private final Runnable autoRefresh=new Runnable(){public void run(){if(isDestroyed())return;if(photoDialog==null&&!batchBusy&&photos().length!=shownCount)showList();refreshHandler.postDelayed(this,5000);}};
 public void onResume(){super.onResume();refreshHandler.postDelayed(autoRefresh,5000);}
 public void onPause(){refreshHandler.removeCallbacks(autoRefresh);super.onPause();}
 public void onCreate(Bundle b){super.onCreate(b);if(b!=null&&b.getString("selected")!=null)selected=new File(RecorderPhotoStore.root(this),b.getString("selected"));for(File f:getCacheDir().listFiles())if(f.getName().startsWith("recorder-export-")&&System.currentTimeMillis()-f.lastModified()>3600000)f.delete();showList();}
 private Bitmap decode(File f,int width)throws Exception{return decodePhoto(f,width);}
 static Bitmap decodePhoto(File f,int width)throws Exception{byte[] bytes=RecorderPhotoStore.read(f);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>width*2)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap image=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(image==null)throw new IOException("invalid JPEG");android.media.ExifInterface exif=new android.media.ExifInterface(new ByteArrayInputStream(bytes));int orientation=exif.getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);Matrix matrix=new Matrix();switch(orientation){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setScale(1,-1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(270);matrix.postScale(-1,1);break;case 8:matrix.setRotate(270);break;}if(!matrix.isIdentity()){Bitmap rotated=Bitmap.createBitmap(image,0,0,image.getWidth(),image.getHeight(),matrix,true);if(rotated!=image)image.recycle();image=rotated;}return image;}
 private void showList(){final int epoch=++generation;LinearLayout box=new LinearLayout(this);box.setOrientation(1);final int inset=(int)(12*getResources().getDisplayMetrics().density);box.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(inset,i.getSystemWindowInsetTop()+inset,inset,i.getSystemWindowInsetBottom()+inset);return i;});TextView info=new TextView(this);info.setText("記録写真\n「グラスから一括取り込み」で保護の有無にかかわらず全記録写真を取得できます。転送中は一覧を自動更新します。");box.addView(info);
  LinearLayout controls=new LinearLayout(this);Button sync=new Button(this),refresh=new Button(this);sync.setText("グラスから一括取り込み");refresh.setText("一覧を更新");controls.addView(sync);controls.addView(refresh);box.addView(controls);
  sync.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("記録写真を一括取り込み")
   .setMessage("グラスの連続撮影を停止して、グラス内の全記録写真をまとめて転送します（KEEP保護のない写真も含む）。両端末でロキを起動し、同じネットワークに接続してください。スマホに保存し内容の一致を確認できた写真は、KEEP保護を含めグラスから削除します。未転送・保存失敗の写真は残ります。")
   .setPositiveButton("撮影を停止して取り込む",(d,w)->{boolean queued=MainActivity.queueBridgeCommand(this,"__LOKI_PHOTO_SYNC__",true);Toast.makeText(this,queued?"グラスへ要求を送信しました。転送後に一覧を更新してください":"要求を送れません。後でもう一度お試しください",Toast.LENGTH_LONG).show();}).setNegativeButton("キャンセル",null).show());
  refresh.setOnClickListener(v->{pageStart=0;checked.clear();showList();});selectionCount=new TextView(this);box.addView(selectionCount);LinearLayout selectionActions=new LinearLayout(this);Button all=new Button(this),none=new Button(this);all.setText("表示中を選択");none.setText("選択解除");selectionActions.addView(all,new LinearLayout.LayoutParams(0,-2,1));selectionActions.addView(none,new LinearLayout.LayoutParams(0,-2,1));box.addView(selectionActions);all.setEnabled(!batchBusy);none.setEnabled(!batchBusy);all.setOnClickListener(v->selectPagePhotos());none.setOnClickListener(v->{if(batchBusy)return;checked.clear();showList();});LinearLayout actions=new LinearLayout(this);bulkSave=new Button(this);bulkDelete=new Button(this);bulkSave.setText("選択して保存");bulkDelete.setText("選択して削除");actions.addView(bulkSave,new LinearLayout.LayoutParams(0,-2,1));actions.addView(bulkDelete,new LinearLayout.LayoutParams(0,-2,1));box.addView(actions);deleteAll=new Button(this);deleteAll.setText("全写真を削除（全ページ）");box.addView(deleteAll,new LinearLayout.LayoutParams(-1,-2));deleteAll.setOnClickListener(v->confirmDeleteAll());updateSelection();bulkSave.setOnClickListener(v->confirmBatch(false));bulkDelete.setOnClickListener(v->confirmBatch(true));ScrollView scroll=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);box.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(box);box.requestApplyInsets();
  File[] files=RecorderPhotoStore.root(this).listFiles(f->f.getName().matches("[0-9]{13}-[a-f0-9-]{36}\\.gcm"));shownCount=files==null?0:files.length;if(files==null||files.length==0){info.append("\n写真はまだありません");checked.clear();updateSelection();return;}Arrays.sort(files,(a,b)->b.getName().compareTo(a.getName()));
  pageStart=Math.min(pageStart,((files.length-1)/PAGE_SIZE)*PAGE_SIZE);final int page=Math.min(files.length-pageStart,PAGE_SIZE);checked.retainAll(Arrays.asList(Arrays.copyOfRange(files,pageStart,pageStart+page)));updateSelection();info.append("\n新しい順："+(pageStart+1)+"〜"+(pageStart+page)+" / 全"+files.length+"枚"); LinearLayout pages=new LinearLayout(this);Button prev=new Button(this),next=new Button(this);prev.setText("前の60枚");next.setText("次の60枚");prev.setEnabled(pageStart>0);next.setEnabled(pageStart+page<files.length);prev.setOnClickListener(v->{pageStart=Math.max(0,pageStart-PAGE_SIZE);checked.clear();showList();});next.setOnClickListener(v->{pageStart+=PAGE_SIZE;checked.clear();showList();});pages.addView(prev);pages.addView(next);box.addView(pages,1);
  float density=getResources().getDisplayMetrics().density;LinearLayout row=null;
  for(int i=0;i<page;i++){
   if(i%2==0){row=new LinearLayout(this);row.setOrientation(0);list.addView(row,new LinearLayout.LayoutParams(-1,-2));}
   File f=files[pageStart+i];LinearLayout card=new LinearLayout(this);card.setOrientation(1);int gap=(int)(6*density);card.setPadding(gap,gap,gap,gap);
   LinearLayout.LayoutParams cell=new LinearLayout.LayoutParams(0,-2,1);row.addView(card,cell);
   CheckBox select=new CheckBox(this);select.setText("選択");select.setChecked(checked.contains(f));select.setOnCheckedChangeListener((button,on)->{if(on)checked.add(f);else checked.remove(f);updateSelection();});card.addView(select);ImageView thumb=new ImageView(this);thumb.setBackgroundColor(Color.rgb(20,20,20));thumb.setScaleType(ImageView.ScaleType.FIT_CENTER);thumb.setContentDescription("記録写真を開く");card.addView(thumb,new LinearLayout.LayoutParams(-1,(int)(240*density)));
   TextView label=new TextView(this);label.setTextSize(13);label.setPadding(0,(int)(6*density),0,(int)(8*density));label.setText(new java.text.SimpleDateFormat("MM/dd HH:mm:ss",Locale.JAPAN).format(new Date(Long.parseLong(f.getName().substring(0,13)))));card.addView(label,new LinearLayout.LayoutParams(-1,-2));card.setOnClickListener(v->preview(f));thumb.setOnClickListener(v->preview(f));label.setOnClickListener(v->preview(f));
   worker.execute(()->{if(epoch!=generation||isDestroyed())return;try{Bitmap image=decode(f,256);runOnUiThread(()->{if(isDestroyed()||epoch!=generation)image.recycle();else thumb.setImageBitmap(image);});}catch(Exception e){runOnUiThread(()->label.setText("写真を読み込めません"));}});
   if(i==page-1&&i%2==0)row.addView(new TextView(this),new LinearLayout.LayoutParams(0,1,1));
  }
 }
 private File[] photos(){File[] files=RecorderPhotoStore.root(this).listFiles(f->f.getName().matches("[0-9]{13}-[a-f0-9-]{36}\\.gcm"));if(files==null)return new File[0];Arrays.sort(files,(a,b)->b.getName().compareTo(a.getName()));return files;}
 static File afterDeletion(File deleted,File[] remaining){Arrays.sort(remaining,(a,b)->b.getName().compareTo(a.getName()));for(File f:remaining)if(f.getName().compareTo(deleted.getName())<0)return f;return remaining.length==0?null:remaining[remaining.length-1];}
 private void preview(File file){final int token=++previewGeneration;worker.execute(()->{try{
  Bitmap image=decode(file,1200);org.json.JSONObject meta=RecorderPhotoStore.metadata(file);String time=new java.text.SimpleDateFormat("yyyy/MM/dd HH:mm:ss",Locale.JAPAN).format(new Date(Long.parseLong(file.getName().substring(0,13))));
  String place=meta.optBoolean("available")?String.format(Locale.JAPAN,"撮影場所：%.6f, %.6f\nスマホ位置・精度 約%.0fm",meta.getDouble("latitude"),meta.getDouble("longitude"),meta.getDouble("accuracyMeters")):"撮影場所：位置情報なし";
  final String details="撮影時刻："+time+"\n"+place+"\nピンチで拡大・ドラッグで移動・ダブルタップで全体表示";
  runOnUiThread(()->{if(isDestroyed()||token!=previewGeneration){image.recycle();return;}
   selected=file;
   if(photoDialog==null){
    photoView=new RecorderPhotoZoomView(this);photoCaption=new TextView(this);photoCaption.setTextSize(13);LinearLayout content=new LinearLayout(this);content.setOrientation(1);content.addView(photoCaption);content.addView(photoView,new LinearLayout.LayoutParams(-1,(int)(getResources().getDisplayMetrics().heightPixels*0.43)));
    previewSave=new Button(this);previewSave.setText("ギャラリーに保存");content.addView(previewSave,new LinearLayout.LayoutParams(-1,-2));LinearLayout bottom=new LinearLayout(this);Button remove=new Button(this),close=new Button(this);remove.setText("スマホから削除");close.setText("閉じる");bottom.addView(remove,new LinearLayout.LayoutParams(0,-2,1));bottom.addView(close,new LinearLayout.LayoutParams(0,-2,1));content.addView(bottom);photoDialog=new AlertDialog.Builder(this).setTitle("記録写真").setView(content).create();previewSave.setOnClickListener(v->saveToGallery(selected));remove.setOnClickListener(v->confirmDelete(selected));close.setOnClickListener(v->photoDialog.dismiss());
    photoDialog.setOnDismissListener(d->{previewGeneration++;if(photoView!=null)photoView.setImageDrawable(null);if(current!=null&&!current.isRecycled())current.recycle();current=null;photoView=null;photoCaption=null;photoDialog=null;if(listDirty&&!isDestroyed()){listDirty=false;pageStart=0;showList();}});
    photoDialog.show();

   }
   Bitmap previous=current;current=image;photoView.setImageBitmap(image);photoCaption.setText(details);if(previous!=null&&!previous.isRecycled())previous.recycle();
  });
 }catch(Exception error){runOnUiThread(()->Toast.makeText(this,"写真を開けません",Toast.LENGTH_LONG).show());}});}
 private void confirmDelete(File file){
  new AlertDialog.Builder(this).setTitle("スマホ内の写真を削除")
   .setMessage("スマホに取り込んだこの1枚を削除します。削除記録により、この写真は再取り込みされません。保存先に書き出したJPEGは削除しません。")
   .setPositiveButton("削除",(dialog,which)->deleteAndAdvance(file))
   .setNegativeButton("キャンセル",null).show();
 }
 private void deleteAndAdvance(File file){worker.execute(()->{try{
    RecorderPhotoStore.delete(this,file);final File next=afterDeletion(file,photos());
    runOnUiThread(()->{if(isDestroyed())return;listDirty=true;if(next!=null&&photoDialog!=null)preview(next);else if(photoDialog!=null)photoDialog.dismiss();else{listDirty=false;pageStart=0;showList();}Toast.makeText(this,"スマホから削除しました",Toast.LENGTH_SHORT).show();});
   }catch(Exception error){runOnUiThread(()->Toast.makeText(this,"削除できませんでした",Toast.LENGTH_LONG).show());}});}
 private void selectPagePhotos(){if(batchBusy)return;checked.clear();Collections.addAll(checked,pagePhotos());showList();}
 private File[] pagePhotos(){File[] all=photos();int start=Math.min(pageStart,all.length);return Arrays.copyOfRange(all,start,Math.min(all.length,start+PAGE_SIZE));}
 private void confirmDeleteAll(){if(batchBusy)return;final File[] all=photos();if(all.length==0)return;new AlertDialog.Builder(this).setTitle("全写真 "+all.length+"枚を削除")
  .setMessage("表示していないページも含め、ロキに取り込んだスマホ内の全写真を削除します。ギャラリーに保存済みのJPEGは残ります。削除した写真は再取り込みされません。")
  .setPositiveButton("全"+all.length+"枚を削除",(d,w)->runBatch(all,true)).setNegativeButton("キャンセル",null).show();}
 private void updateSelection(){if(selectionCount==null)return;selectionCount.setText("選択："+checked.size()+"枚（表示中のページのみ）");bulkSave.setEnabled(!batchBusy&&!checked.isEmpty());bulkDelete.setEnabled(!batchBusy&&!checked.isEmpty());if(deleteAll!=null)deleteAll.setEnabled(!batchBusy&&photos().length>0);}
 private void confirmBatch(boolean delete){if(batchBusy||checked.isEmpty())return;final File[] files=checked.toArray(new File[0]);new AlertDialog.Builder(this).setTitle(files.length+"枚を"+(delete?"削除":"保存")).setMessage(delete?"選択したスマホ内の写真だけを削除します。ギャラリーに保存済みのJPEGは残ります。削除した写真は再取り込みされません。":"選択した写真をJPEGとしてギャラリーのLokiアルバムへ保存します。").setPositiveButton(delete?"削除":"保存",(d,w)->runBatch(files,delete)).setNegativeButton("キャンセル",null).show();}
 private void runBatch(File[] files,boolean delete){if(batchBusy)return;if(!delete&&Build.VERSION.SDK_INT<29&&checkSelfPermission(android.Manifest.permission.WRITE_EXTERNAL_STORAGE)!=android.content.pm.PackageManager.PERMISSION_GRANTED){permissionPendingBatch=files;requestPermissions(new String[]{android.Manifest.permission.WRITE_EXTERNAL_STORAGE},453);return;}batchBusy=true;updateSelection();worker.execute(()->{int success=0;final Set<File> done=new HashSet<>();for(File f:files){try{if(delete)RecorderPhotoStore.delete(this,f);else writeGallery(f);done.add(f);success++;}catch(Exception failure){}}final int count=success;runOnUiThread(()->{batchBusy=false;checked.removeAll(done);if(isDestroyed())return;showList();Toast.makeText(this,count+"枚を"+(delete?"削除":"保存")+"しました"+(count<files.length?"。失敗した"+(files.length-count)+"枚は削除・保存せず残っています":""),Toast.LENGTH_LONG).show();});});}
 private File permissionPendingPhoto;
 private void saveToGallery(File file){
  if(android.os.Build.VERSION.SDK_INT<29&&checkSelfPermission(android.Manifest.permission.WRITE_EXTERNAL_STORAGE)!=android.content.pm.PackageManager.PERMISSION_GRANTED){permissionPendingPhoto=file;requestPermissions(new String[]{android.Manifest.permission.WRITE_EXTERNAL_STORAGE},452);return;}
  if(photoDialog!=null)previewSave.setEnabled(false);
  worker.execute(()->{try{android.net.Uri uri=writeGallery(file);runOnUiThread(()->Toast.makeText(this,"ギャラリーに保存しました",Toast.LENGTH_LONG).show());}
   catch(Exception error){runOnUiThread(()->Toast.makeText(this,"ギャラリーへの保存に失敗しました",Toast.LENGTH_LONG).show());}
   finally{runOnUiThread(()->{if(photoDialog!=null)previewSave.setEnabled(true);});}});
 }
 public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==453){File[] files=permissionPendingBatch;permissionPendingBatch=null;if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED&&files!=null)runBatch(files,false);else Toast.makeText(this,"写真の保存にはストレージの許可が必要です",Toast.LENGTH_LONG).show();}if(request==452){File file=permissionPendingPhoto;permissionPendingPhoto=null;if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED&&file!=null)saveToGallery(file);else Toast.makeText(this,"写真の保存にはストレージの許可が必要です",Toast.LENGTH_LONG).show();}}
 private android.net.Uri writeGallery(File file)throws Exception{
  android.content.SharedPreferences saved=getSharedPreferences("recorder_gallery_exports",MODE_PRIVATE);String previous=saved.getString(file.getName(),"");
  if(!previous.isEmpty()){android.net.Uri existing=android.net.Uri.parse(previous);try(android.content.res.AssetFileDescriptor asset=getContentResolver().openAssetFileDescriptor(existing,"r")){if(asset!=null)return existing;}catch(java.io.FileNotFoundException deleted){}}
  android.content.ContentValues values=new android.content.ContentValues();values.put(android.provider.MediaStore.Images.Media.DISPLAY_NAME,file.getName().replace(".gcm",".jpg"));values.put(android.provider.MediaStore.Images.Media.MIME_TYPE,"image/jpeg");values.put(android.provider.MediaStore.Images.Media.DATE_TAKEN,Long.parseLong(file.getName().substring(0,13)));
  if(android.os.Build.VERSION.SDK_INT>=29){values.put(android.provider.MediaStore.Images.Media.RELATIVE_PATH,android.os.Environment.DIRECTORY_PICTURES+"/Loki");values.put(android.provider.MediaStore.Images.Media.IS_PENDING,1);}
  android.net.Uri uri=getContentResolver().insert(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("gallery insert failed");
  try{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("gallery output failed");writeJpeg(file,out);}
   if(android.os.Build.VERSION.SDK_INT>=29){android.content.ContentValues ready=new android.content.ContentValues();ready.put(android.provider.MediaStore.Images.Media.IS_PENDING,0);if(getContentResolver().update(uri,ready,null,null)!=1)throw new IOException("gallery publish failed");}
   saved.edit().putString(file.getName(),uri.toString()).apply();return uri;
  }catch(Exception failure){getContentResolver().delete(uri,null,null);throw failure;}
 }
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==451&&result==RESULT_OK&&data!=null&&data.getData()!=null){File f=selected;android.net.Uri uri=data.getData();worker.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException();writeJpeg(f,out);runOnUiThread(()->Toast.makeText(this,"JPEGを保存しました",Toast.LENGTH_LONG).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"保存に失敗しました",Toast.LENGTH_LONG).show());}});}}
 protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);if(selected!=null)b.putString("selected",selected.getName());}
 private void writeJpeg(File f,OutputStream out)throws Exception{exportJpeg(this,f,out);}
 static void exportJpeg(android.content.Context context,File f,OutputStream out)throws Exception{
  File temp=File.createTempFile("recorder-export-",".jpg",context.getCacheDir());try{
   org.json.JSONObject meta=RecorderPhotoStore.metadata(f);byte[] jpeg=RecorderPhotoStore.read(f);if(meta.optBoolean("readOverlay"))jpeg=ImageQuestions.normalize(jpeg,8000000,ReadCaptureContext.lines(meta));java.nio.file.Files.write(temp.toPath(),jpeg);android.media.ExifInterface exif=new android.media.ExifInterface(temp.getAbsolutePath());long at=Long.parseLong(f.getName().substring(0,13));String time=new java.text.SimpleDateFormat("yyyy:MM:dd HH:mm:ss",Locale.US).format(new Date(at));exif.setAttribute(android.media.ExifInterface.TAG_DATETIME,time);exif.setAttribute(android.media.ExifInterface.TAG_DATETIME_ORIGINAL,time);exif.setAttribute("OffsetTimeOriginal",new java.text.SimpleDateFormat("XXX",Locale.US).format(new Date(at)));if(meta.optBoolean("available")){double lat=meta.getDouble("latitude"),lon=meta.getDouble("longitude");exif.setAttribute(android.media.ExifInterface.TAG_GPS_LATITUDE,gps(Math.abs(lat)));exif.setAttribute(android.media.ExifInterface.TAG_GPS_LATITUDE_REF,lat<0?"S":"N");exif.setAttribute(android.media.ExifInterface.TAG_GPS_LONGITUDE,gps(Math.abs(lon)));exif.setAttribute(android.media.ExifInterface.TAG_GPS_LONGITUDE_REF,lon<0?"W":"E");exif.setAttribute(android.media.ExifInterface.TAG_USER_COMMENT,"Location source: phone; accuracy meters: "+meta.getDouble("accuracyMeters"));}exif.saveAttributes();try(InputStream in=new FileInputStream(temp)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))>0)out.write(buffer,0,n);}
  }finally{temp.delete();}
 }
 private static String gps(double value){int degrees=(int)value;double minutes=(value-degrees)*60;int whole=(int)minutes;return degrees+"/1,"+whole+"/1,"+Math.round((minutes-whole)*60000000)+"/1000000";}
 public void onDestroy(){refreshHandler.removeCallbacks(autoRefresh);generation++;previewGeneration++;if(photoDialog!=null)photoDialog.dismiss();worker.shutdownNow();super.onDestroy();}
}
